	if (start == null) throw new NullPointerException();
	if (stop == null) throw new NullPointerException();

	// Initialize the starting circulator
	OuterFaceCirculator cir = new OuterFaceCirculator(start, stop, dir);

	// Iterate through the circulator until a node is found that satisfies the predicate
	while (cir.hasNext()) {
		Node node = cir.next();
		if (predicate.test(node)) {
			return cir;
		}
	}

