public List<Integer> computeLowerBounds(List<K> keys) {
    // Initialize the lower bounds list with the minimum value
    List<Integer> lowerBounds = new ArrayList<>(Collections.min(keys));

    // Iterate over the keys and compute the lower bound for each key
    for (K key : keys) {
        // Find the index of the key in the list
        int index = keys.indexOf(key);

        // Set the lower bound to the maximum of the previous lower bound and the index
        lowerBounds.set(index, Math.max(lowerBounds.get(index), index));
    }

    // Return the list of lower bounds
    return lowerBounds;
}

