private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys.isEmpty()) {
        return Collections.emptyList();
    }
    // initialize the upper bounds with the first key
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    upperBounds.add(keys.get(0));
    // loop through the remaining keys and update the upper bounds
    for (int i = 1; i < keys.size(); i++) {
        K key = keys.get(i);
        int index = upperBounds.size() - 1;
        while (index >= 0 && upperBounds.get(index) < key) {
            index--;
        }
        upperBounds.add(index, key);
    }
    return upperBounds;
}

