static int nullSafeHashCode(long[] array){
    // Check if the array is null
    if (array == null){
        // If the array is null, return 0
        return 0;
    }

    // Initialize a hash code value
    int hashCode = 193;

    // Loop through the array and combine the hash codes of each long value
    for (int i = 0; i < array.length; i++){
        // Calculate the hash code of the current long value
        long longHashCode = Long.hashCode(array[i]);

        // Combine the hash code with the running hash code
        hashCode = 29 * hashCode + (int) (longHashCode ^ (longHashCode >>> 32));
    }

    // Return the final hash code
    return hashCode;
}

