public static String applyRelativePath(String path, String relativePath) {
    // Since this is a relative path, we need to resolve it against the current directory
    // First, we split the path into components
    String[] components = path.split("/");
    // Then, we split the relative path into components
    String[] relativeComponents = relativePath.split("/");

    // We'll use a stack to build the result path, starting with the components of the current path
    Stack<String> resultComponents = new Stack<>();
    for (String component : components) {
        resultComponents.push(component);
    }

    // Now, we'll process the relative path components, popping the stack and adjusting it as necessary
    for (String component : relativeComponents) {
        if (component.equals("..")) {
            // ".." means to move up one directory. We pop the last component of the result path.
            resultComponents.pop();
        } else if (!component.isEmpty()) {
            // Anything else (including the empty string) means to add a new component to the result path.
            resultComponents.push(component);
        }
    }

    // Finally, we join the result path into a string
    String resultPath = "";
    for (String component : resultComponents) {
        if (resultComponents.size() > 1) {
            resultPath += "/";
        }
        resultPath += component;
    }
    return resultPath;
}

