public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }

    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0 || index > strLen) {
        return false;
    }
    if (subLen == 0) {
        return true;
    }

    for (int i = 0; i < subLen; i++) {
        // Check the character at i in the substring
        char c = substring.charAt(i);
        // Check if the i + index in the string is within the string bounds
        if (i + index >= strLen) {
            return false;
        }
        // Check if the character at i + index is the same as the character in the substring
        if (c != str.charAt(i + index)) {
            return false;
        }
    }

    return true;
}

