    // Initialize empty list to store the paths of inactive nodes
    List<String> inactiveNodePaths = new ArrayList<>();

    // Iterate through the category tree and find all inactive nodes
    for (int i = 0; i < tree.getRowCount(); i++) {
        TreeNode node = (TreeNode) tree.getPathForRow(i).getLastPathComponent();
        if (!node.isActive()) {
            inactiveNodePaths.add(tree.getPathForRow(i).toString());
        }
    }

    // Remove inactive nodes from the tree
    for (String path : inactiveNodePaths) {
        int removed = 0;
        // Use BFS to find and remove inactive nodes
        List<String> subTree = listSubTreeBFS(path);
        for (String subPath : subTree) {
            int row = tree.getRowForPath(new TreePath(subPath));
            // Remove inactive node from tree
            tree.removeNode(row);
            // Increment number of removed nodes
            removed++;
        }
    }

    return inactiveNodePaths.size();
}

