public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Read the file content
    String content = FileUtils.readFileToString(file, StandardCharsets.UTF_8);

    // Parse the file content and extract thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    for (Matcher matcher : Pattern.compile("(?m)\\[(\\d+)(?:-\\d+)?\\]").matcher(content)) {
        String timeRange = matcher.group(1);
        List<ThreadSnapshot> timeRangeThreadSnapshots = new ArrayList<>();
        for (Matcher threadMatcher : Pattern.compile("\\d+").matcher(timeRange)) {
            String threadId = threadMatcher.group(1);
            List<ThreadSnapshot.StackFrame> stackFrames = new ArrayList<>();
            for (Matcher stackFrameMatcher : Pattern.compile("(?<=@\\d+\\()(?:(?!@).)+(?=\\))").matcher(content)) {
                stackFrames.add(new ThreadSnapshot.StackFrame(stackFrameMatcher.group(1), stackFrameMatcher.group(2)));
            }
            timeRangeThreadSnapshots.add(new ThreadSnapshot(threadId, stackFrames));
        }
        threadSnapshots.add(new ProfileAnalyzeTimeRange(timeRange, timeRangeThreadSnapshots));
    }

    // Filter thread snapshots based on time ranges
    List<ThreadSnapshot> filteredThreadSnapshots = new ArrayList<>();
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        for (ThreadSnapshot threadSnapshot : threadSnapshots) {
            if (timeRange.getTimeRange().equals(threadSnapshot.getThreadId())) {
                filteredThreadSnapshots.add(threadSnapshot);
            }
        }
    }

    return filteredThreadSnapshots;
}

