public JsonObject convertProperties(List<KeyStringValuePair> properties) {
    JsonObject sourceData = new JsonObject();

    for (KeyStringValuePair property : properties) {
        switch (property.getValue().getType()) {
            case BOOLEAN:
                sourceData.addProperty(property.getKey(), property.getValue().getBooleanValue());
                break;
            case SHORT:
            case INTEGER:
            case LONG:
            case FLOATING_POINT:
                sourceData.addProperty(property.getKey(), property.getValue().getDoubleValue());
                break;
            case STRING:
                sourceData.addProperty(property.getKey(), property.getValue().getStringValue());
                break;
            case OBJECT:
                sourceData.add(property.getKey(), convertProperties(property.getValue().getProperties()));
                break;
            default:
                break;
        }
    }

    return sourceData;
}

