	if (str == null) {
		return null;
	}

	int strLen = str.length();
	int charCount = 0;
	int byteCount = 0;

	for (int i = 0; i < strLen; i++) {
		charCount++;
		if (str.charAt(i) > 0xFFFF) {
			charCount++;
		}
	}

	checkArgument(charCount <= session.getCharacterBufferSize(), "UTF8 string is too long: %s characters, maximum is %s", charCount, session.getCharacterBufferSize());

	if (byteCount == 0) {
		return lb;
	}

	lb.linkLengths(charCount);

	int position = lb.getPosition();
	lb.skip(2);

	for (int i = 0; i < strLen; i++) {
