public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;

    // Write the contents of the buffer to the output
    do {
        // Get the current chunk of the buffer
        ByteChunk chunk = node.getData();

        // Get the number of bytes remaining in the chunk
        int chunkRemaining = chunk.getRemaining();

        // If there are no bytes remaining, move to the next chunk
        if (chunkRemaining == 0) {
            node = node.getNext();
            continue;
        }

        // Write the chunk to the output
        totalSize += out.write(chunk.getData(), chunkRemaining);
    } while (node != null);

    return totalSize;
}

